'use strict';
/*
 * char-graph.js - minimal id-based character graph engine (synthetic test fixture for sg-data-pack)
 *
 * Default data is embedded as literals; mount() accepts options to override.
 * __fromPack reconstructs the defaults from a Data Pack (used by the equivalence test).
 */
var CharGraph = (function () {
  var options = (typeof options !== 'undefined') ? options : undefined; // browser-global guard
  var chars = (options && options.chars) || {
    alice: { name: 'Alice', kind: 'person' },
    bob: { name: 'Bob', kind: 'person' }
  };
  var edges = (options && options.edges) || [
    { a: 'alice', b: 'bob', type: 'family' }
  ];

  function mount(root, options) {
    options = options || {};
    var c = (options && options.chars) || chars;
    var e = (options && options.edges) || edges;
    // rendering omitted - data layer only
    return { chars: c, edges: e };
  }

  // Reconstruct engine defaults from a Data Pack (equivalence-test hook)
  function __fromPack(pack) {
    var p = pack || {};
    return {
      chars: Object.assign({}, p.entities || {}),
      allEdges: (p.relations || []).map(function (r) {
        return { a: r.a, b: r.b, type: r.type };
      })
    };
  }

  return { mount: mount, __fromPack: __fromPack };
})();

// expose for both browser-global and Node (equivalence test runs under Node)
if (typeof globalThis !== 'undefined') globalThis.CharGraph = CharGraph;

'use strict';
/*
 * Extraction config for char-graph (t01-id-based)
 */

const LIB_DIR = '/Users/tangyaoyue/DEV/tool-self-harness/tasks/held-in/t01-id-based/input';

module.exports = {
  libId: 'char-graph',
  libDir: LIB_DIR,
  engineFile: 'lib/src/char-graph.js',
  globalName: 'CharGraph',

  literals: [
    { key: 'chars', pattern: /var chars = \(options && options\.chars\) \|\|/ },
    { key: 'edges', pattern: /var edges = \(options && options\.edges\) \|\|/ },
  ],

  meta: {
    title: 'Character Graph (id-based)',
    hero: 'alice',
    source: 'Embedded data from original case page (decomposition export)',
    fetchedAt: new Date().toISOString().slice(0, 10)
  },

  buildPack(defaults) {
    // ① Entity table: chars already have `kind`, use directly
    const entities = {};
    for (const [id, c] of Object.entries(defaults.chars)) {
      entities[id] = Object.assign({}, c);
    }

    // ② Alias table: display name → id
    const aliases = {};
    for (const [id, c] of Object.entries(defaults.chars)) {
      aliases[c.name] = id;
    }

    // ③ Relation-type registry
    const relationTypes = {
      family: { label: 'Family' },
    };

    // ④ Master edge list
    const relations = (defaults.edges || []).map(function (e) {
      return { a: e.a, b: e.b, type: e.type, label: e.type };
    });

    const pack = {
      entities,
      aliases,
      relationTypes,
      relations,
    };

    // ⑤ Provenance stamping
    const stamp = function (origin) {
      return {
        origin: origin,
        sourceUrl: null,
        fetchedAt: new Date().toISOString().slice(0, 10),
        confidence: 1.0,
        note: 'Baseline data (embedded in original case page); original sourceUrl lost'
      };
    };
    pack.provenance = {
      entities: Object.fromEntries(Object.keys(pack.entities).map(function (id) { return [id, stamp('engine-embedded-defaults')]; })),
      relations: Object.fromEntries(pack.relations.map(function (r) { return [r.a + '::' + r.b, stamp('engine-embedded-defaults')]; }))
    };

    return pack;
  },

  // Losslessness check: fromPack(pack)[from] deep-equals defaults[lit]
  equivalence: [
    { lit: 'chars', from: 'chars' },
    { lit: 'edges', from: 'allEdges' },
  ],

  domainSchema: {
    type: 'object',
    description: 'Library-specific data collections',
    additionalProperties: true
  }
};

